def brand(reversed=False):
    mark = "mihrab-reverse.svg" if reversed else "mihrab-color.svg"
    return f'<a href="index.html" class="brand" title="Jaffery Center home"><img class="brand-symbol" src="assets/brand/{mark}" alt="" width="38" height="38"><span class="brand-text">Jaffery Center<small>Roanoke, Virginia</small></span></a>'

_nav_markup = None

def header(active):
    global _nav_markup
    if _nav_markup is None:
        rendered = subprocess.run(['node', '--import', 'tsx', 'src/render-nav.tsx'], check=True, capture_output=True, text=True)
        _nav_markup = json.loads(rendered.stdout)
    label = 'Support us' if active == 'Give' else active
    fallback_links = ''.join(f'<a href="{path}">{"Support us" if text == "Give" else text}</a>' for path, text in PAGES)
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap navrow">{brand()}<div id="liquid-nav-root" class="liquid-nav-root">{_nav_markup[label]}</div></div><noscript><style>.mobile-menu-button{{display:none!important}}@media(max-width:1020px){{.nojs-nav{{display:grid!important}}}}</style><nav class="nojs-nav" aria-label="Navigation without JavaScript">{fallback_links}</nav></noscript></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div>{brand(True)}<p>Faith, family, and community in Roanoke, Virginia. Everyone is welcome.</p><p class="footer-invocation" lang="ar" dir="rtl">بِسْمِ ٱللَّٰهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</p></div><div><h3>Explore</h3><div class="footer-links"><a href="index.html">Home</a><a href="about.html">About us</a><a href="programs.html">Programs</a><a href="sunday-school.html">Sunday School</a><a href="visit.html">Visit & contact</a><a href="donate.html">Support us</a></div></div><div><h3>Find us</h3><div class="footer-links"><span>3031 Preston Avenue<br>Roanoke, VA 24012</span><a href="mailto:{EMAIL}">{EMAIL}</a><a href="{MAP_URL}" target="_blank" rel="noopener noreferrer">Get directions ↗</a></div></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Jaffery Center of Roanoke.</span><span>Made with care for our community.</span></div></div></footer>'''

def hero(title, description, current):
    return f'''<section class="page-hero"><div id="hero-hills-root" class="hero-hills" aria-hidden="true"></div><div class="wrap"><div class="crumb"><a href="index.html">Home</a> &nbsp;/&nbsp; {current}</div><h1>{title}</h1><p>{description}</p></div></section>'''

def page(filename, title, description, body, active):
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#10332f"><meta name="description" content="{escape(description, quote=True)}"><title>{escape(title)} | Jaffery Center of Roanoke</title><link rel="icon" type="image/svg+xml" href="assets/brand/favicon.svg"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="components/ui/liquid-glass-navbar.css"><script type="module" src="/src/navbar-entry.tsx"></script><script type="module" src="/src/hills-entry.tsx"></script><script type="module" src="/site.js"></script></head><body>{SPRITE}{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
    Path(filename).write_text(html, encoding='utf-8')

def feature(title, text, label, destination, glyph, delay=''):
    return f'''<article class="feature-card glass--frosted reveal {delay}"><span class="feature-icon">{icon(glyph)}</span><h3>{title}</h3><p>{text}</p>{link(label,destination)}</article>'''

